fn doctype_decl_handlers<StartCallback, EndCallback>(
    start: Option<StartCallback>,
    end: Option<EndCallback>,
) -> DoctypeDeclHandlers
where
    StartCallback: StartDoctypeDeclCallback + 'static,
    EndCallback: EndCdataSectionCallback + 'static,
{
    DoctypeDeclHandlers {
        start: start.map(|callback| {
            std::sync::Arc::new(StartDoctypeDeclCallbackAdapter::new(callback))
        }),
        end: end.map(cdata_section_callback_adapter),
    }
}

/// Typed doctype callback registrations prepared at the ABI boundary.  The
/// parser-side setter only needs these owned adapters and an opaque parser
/// address key.
struct DoctypeDeclHandlers {
    start: Option<std::sync::Arc<StartDoctypeDeclCallbackAdapter>>,
    end: Option<std::sync::Arc<CdataSectionCallbackAdapter>>,
}

// C exposes two handler-context modes: callbacks receive the caller's user
// data by default, or the parser handle after XML_UseParserAsHandlerArg.
// Recording that choice avoids retaining an opaque foreign pointer in parser
// state; callback sites materialize it only for the duration of the call.
#[derive(Copy, Clone, Eq, PartialEq)]
pub enum HandlerArg {
    UserData,
    Parser,
}

// `XML_GetUserData` is a C macro which reads the first word of an
// `XML_ParserStruct` as `void *`.  Keep that ABI word-sized while retaining
// only an opaque address token in Rust state.  The token is never
// dereferenced by Rust; the C-callback boundary resolves its matching opaque
// context, whose lifetime contract belongs to the caller of XML_SetUserData.
#[derive(Copy, Clone)]
struct CallbackContextToken(usize);

impl CallbackContextToken {
    const EMPTY: Self = Self(0);

    fn from_ffi_address(address: usize) -> Self {
        Self(address)
    }
}

#[repr(transparent)]
struct CallbackContext(std::sync::atomic::AtomicUsize);

impl CallbackContext {
    fn empty() -> Self {
        Self(std::sync::atomic::AtomicUsize::new(0))
    }

    fn clear(&self) {
        self.store(CallbackContextToken::EMPTY);
    }

    fn load(&self) -> CallbackContextToken {
        CallbackContextToken(self.0.load(std::sync::atomic::Ordering::Relaxed))
    }

    fn store(&self, value: CallbackContextToken) {
        self.0
            .store(value.0, std::sync::atomic::Ordering::Relaxed);
    }
}

const CALLBACK_CONTEXT_SIZE_MATCHES_C_VOID_POINTER: () = assert!(
    ::core::mem::size_of::<CallbackContext>() == ::core::mem::size_of::<*mut ::core::ffi::c_void>()
);
const CALLBACK_CONTEXT_ALIGNMENT_MATCHES_C_VOID_POINTER: () = assert!(
    ::core::mem::align_of::<CallbackContext>() == ::core::mem::align_of::<*mut ::core::ffi::c_void>()
);

// C callback arguments are materialized at the boundary, not recovered from
// the parser's ABI word.  This avoids an integer-to-pointer conversion while
// retaining the caller-owned context as a private opaque token; it is only
// materialized while dispatching a C callback.  Parser entries are removed on
// reset/free.
#[derive(Clone)]
struct CallbackContextRegistration {
    context: std::sync::Arc<dyn std::any::Any + Send + Sync>,
}

static CALLBACK_CONTEXTS: std::sync::OnceLock<
    std::sync::Mutex<std::collections::HashMap<usize, CallbackContextRegistration>>,
> = std::sync::OnceLock::new();

fn clear_callback_context(parser_key: usize) {
    CALLBACK_CONTEXTS
        .get_or_init(|| std::sync::Mutex::new(std::collections::HashMap::new()))
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner())
        .remove(&parser_key);
}

fn copy_callback_context(source: &XML_ParserStruct, destination: &XML_ParserStruct) {
    let source_key = std::ptr::from_ref(source).addr();
    let destination_key = std::ptr::from_ref(destination).addr();
    let mut contexts = CALLBACK_CONTEXTS
        .get_or_init(|| std::sync::Mutex::new(std::collections::HashMap::new()))
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner());
    if let Some(context) = contexts.get(&source_key).cloned() {
        contexts.insert(destination_key, context);
    } else {
        contexts.remove(&destination_key);
    }
}

macro_rules! callback_context_pointer {
    ($parser:expr) => {{
        let parser_ref: &XML_ParserStruct = $parser;
        CALLBACK_CONTEXTS
            .get_or_init(|| std::sync::Mutex::new(std::collections::HashMap::new()))
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner())
            .get(&std::ptr::from_ref(parser_ref).addr())
            .and_then(|registration| {
                registration
                    .context
                    .downcast_ref::<std::sync::atomic::AtomicPtr<::core::ffi::c_void>>()
            })
            .map(|context| context.load(std::sync::atomic::Ordering::Relaxed))
            .unwrap_or(::core::ptr::null_mut())
    }};
}

macro_rules! handler_arg_from_state {
    ($parser:expr) => {{
        let parser: &XML_ParserStruct = &*$parser;
        match parser.m_handlerArg {
            HandlerArg::UserData => callback_context_pointer!(parser),
            HandlerArg::Parser => std::ptr::from_ref(&*parser).cast_mut().cast(),
        }
    }};
}

/// Captures a C default handler behind a typed event adapter.
///
/// Registration is the callback ABI boundary.  Parser dispatch later supplies
/// only a live parser borrow and a bounded XML-character slice.
fn default_callback_adapter(
    callback: std::sync::Arc<dyn DefaultCallback>,
) -> std::sync::Arc<DefaultCallbackAdapter> {
    let callback = std::sync::Arc::new(move |event: DefaultCallbackEvent<'_>| {
        let Ok(len) = ::core::ffi::c_int::try_from(event.data.len()) else {
            return;
        };
        let Some(callback) = (callback.as_ref() as &dyn std::any::Any).downcast_ref::<
            extern "C" fn(
                *mut ::core::ffi::c_void,
                *const crate::expat_external_h::XML_Char,
                ::core::ffi::c_int,
            ),
        >() else {
            return;
        };
        // The typed event provides a live parser context and a bounded,
        // parser-owned character slice for this synchronous C callback.
        callback(handler_arg_from_state!(event.parser), event.data.as_ptr(), len);
    });
    std::sync::Arc::new(DefaultCallbackAdapter { callback })
}

impl StartDoctypeDeclCallbackAdapter {
    fn invoke(&self, event: StartDoctypeDeclCallbackEvent<'_>) {
        let Some(callback) = (self.callback.as_ref() as &dyn std::any::Any).downcast_ref::<
            unsafe extern "C" fn(
                *mut ::core::ffi::c_void,
                *const crate::expat_external_h::XML_Char,
                *const crate::expat_external_h::XML_Char,
                *const crate::expat_external_h::XML_Char,
                ::core::ffi::c_int,
            ),
        >() else {
            return;
        };
        unsafe {
            callback(
                handler_arg_from_state!(event.parser),
                event.name.map_or(::core::ptr::null(), |chars| chars.as_ptr()),
                event
                    .system_id
                    .map_or(::core::ptr::null(), |chars| chars.as_ptr()),
                event
                    .public_id
                    .map_or(::core::ptr::null(), |chars| chars.as_ptr()),
                event.has_internal_subset,
            );
        }
    }
}

impl CommentCallbackAdapter {
    fn invoke(&self, invocation: CommentCallbackInvocation<'_>) {
        let Some(callback) = (self.callback.as_ref() as &dyn std::any::Any).downcast_ref::<
            extern "C" fn(
                *mut ::core::ffi::c_void,
                *const crate::expat_external_h::XML_Char,
            ),
        >() else {
            return;
        };
        // `invocation` guarantees the data pointer is a live, terminated
        // parser-owned XML-character sequence for this call.
        callback(
            handler_arg_from_state!(invocation.parser),
            invocation.data.as_ptr(),
        )
    }
}

impl CharacterDataCallbackAdapter {
    fn invoke(&self, event: CharacterDataCallbackEvent<'_>) {
        (self.callback)(event);
    }
}

/// Captures a C character-data handler behind a typed event adapter.
///
/// Registration is the callback ABI boundary.  Later parser dispatch only
/// supplies a live parser borrow and a bounded XML-character slice.
fn character_data_callback_adapter(
    callback: std::sync::Arc<dyn CharacterDataCallback>,
) -> std::sync::Arc<CharacterDataCallbackAdapter> {
    let callback = std::sync::Arc::new(move |event: CharacterDataCallbackEvent<'_>| {
        let Ok(len) = ::core::ffi::c_int::try_from(event.data.len()) else {
            return;
        };
        let Some(callback) = (callback.as_ref() as &dyn std::any::Any).downcast_ref::<
            extern "C" fn(
                *mut ::core::ffi::c_void,
                *const crate::expat_external_h::XML_Char,
                ::core::ffi::c_int,
            ),
        >() else {
            return;
        };
        // The typed event provides a live parser context and a bounded,
        // parser-owned character slice for this synchronous C callback.
        callback(handler_arg_from_state!(event.parser), event.data.as_ptr(), len);
    });
    std::sync::Arc::new(CharacterDataCallbackAdapter { callback })
}

impl TwoXmlCharCallbackAdapter {
    fn invoke(&self, event: TwoXmlCharCallbackEvent<'_>) {
        (self.callback)(event);
    }
}

/// Converts a registered two-string C callback into typed parser dispatch.
///
/// The unsafe ABI call is isolated at callback registration.  Invocation
/// thereafter accepts only live parser and XML-character views.
fn two_xml_char_callback_adapter(
    callback: std::sync::Arc<dyn TwoXmlCharCallback>,
) -> std::sync::Arc<dyn Fn(TwoXmlCharCallbackEvent<'_>) + Send + Sync> {
    std::sync::Arc::new(move |event: TwoXmlCharCallbackEvent<'_>| {
        let Some(callback) = (callback.as_ref() as &dyn std::any::Any).downcast_ref::<
            unsafe extern "C" fn(
                *mut ::core::ffi::c_void,
                *const crate::expat_external_h::XML_Char,
                *const crate::expat_external_h::XML_Char,
            ),
        >() else {
            return;
        };
        unsafe {
            callback(
                handler_arg_from_state!(event.parser),
                event.first.map_or(::core::ptr::null(), |chars| chars.as_ptr()),
                event.second.map_or(::core::ptr::null(), |chars| chars.as_ptr()),
            );
        }
    })
}

/// Converts one registered C callback into the typed, synchronous callback
/// used by CDATA and end-doctype dispatch.  This is the sole ABI call site
/// for that shared adapter family; parser dispatch itself retains only a
/// parser reference.
fn cdata_section_callback_adapter<Callback>(
    callback: Callback,
) -> std::sync::Arc<CdataSectionCallbackAdapter>
where
    Callback: EndCdataSectionCallback + 'static,
{
    let callback = std::sync::Arc::new(callback);
    let callback = std::sync::Arc::new(move |parser: &XML_ParserStruct| {
        let Some(callback) = (callback.as_ref() as &dyn std::any::Any)
            .downcast_ref::<extern "C" fn(*mut ::core::ffi::c_void)>()
        else {
            return;
        };
        // The callback receives only the caller-owned opaque context or the
        // current parser handle, selected by the parser's handler-argument
        // mode. Both are materialized for this immediate C-ABI call.
        callback(handler_arg_from_state!(parser))
    });
    std::sync::Arc::new(CdataSectionCallbackAdapter { callback })
}

impl CdataSectionCallbackAdapter {
    fn invoke(&self, parser: &XML_ParserStruct) {
        (self.callback)(parser)
    }
}

impl StartElementCallbackAdapter {
    fn new<Callback>(callback: Callback) -> Self
    where
        Callback: StartElementCallback + 'static,
    {
        Self {
            callback: std::sync::Arc::new(callback),
        }
    }

    fn invoke(&self, event: StartElementCallbackEvent<'_>) -> bool {
        let Some(callback) = self.callback.downcast_ref::<
            extern "C" fn(
                *mut ::core::ffi::c_void,
                *const crate::expat_external_h::XML_Char,
                *mut *const crate::expat_external_h::XML_Char,
            ),
        >() else {
            return false;
        };
        let mut attribute_pointers = Vec::new();
        if attribute_pointers
            .try_reserve_exact(event.attributes.len().saturating_add(1))
            .is_err()
        {
            return false;
        }
        attribute_pointers.extend(event.attributes.iter().map(|value| value.as_ptr()));
        attribute_pointers.push(::core::ptr::null());
        // The registration boundary accepts only this ABI callback shape.
        // `dispatch_start_element_callback` owns the XML-character buffers,
        // and the vector above owns the writable, null-terminated attribute
        // pointer array for the full duration of this call.
        callback(
            handler_arg_from_state!(event.parser),
            event.name.as_ptr(),
            attribute_pointers.as_mut_ptr(),
        );
        true
    }
}

/// Stages a start-element event in owned XML-character vectors before making
/// the one ABI callback.  Attribute pool handles, rather than raw pointers,
/// survive the parser work leading up to this point; the local pointer array
/// is valid for precisely this foreign call.
fn dispatch_start_element_callback(
    callback: &StartElementCallbackAdapter,
    parser: &XML_ParserStruct,
    name: &[crate::expat_external_h::XML_Char],
    attributes: &[Option<StartElementAttributeValue>],
) -> bool {
    let mut callback_name = Vec::new();
    if callback_name.try_reserve_exact(name.len()).is_err() {
        return false;
    }
    callback_name.extend_from_slice(name);

    let mut callback_attributes = Vec::new();
    if callback_attributes
        .try_reserve_exact(attributes.len().saturating_sub(1))
        .is_err()
    {
        return false;
    }
    for value in attributes {
        let Some(value) = value else {
            break;
        };
        callback_attributes.push(match start_element_attribute_chars(parser, *value) {
            Some(value) => value,
            None => return false,
        });
    }
    callback.invoke(StartElementCallbackEvent {
        parser,
        name: &callback_name,
        attributes: &callback_attributes,
    })
}

/// Invokes a start-doctype callback from the parser's retained pool values.
/// The declaration strings are pool-owned, NUL-terminated XML character
/// sequences, so prolog processing can remain on typed parser state and this
/// narrow boundary contains the sole ABI call.
fn dispatch_start_doctype_decl_callback(
    callback: &StartDoctypeDeclCallbackAdapter,
    parser: &XML_ParserStruct,
    has_internal_subset: ::core::ffi::c_int,
) {
    let doctype_name = parser
        .m_doctypeName
        .and_then(|name| parser.m_tempPool.chars_from(name));
    let doctype_pubid = parser
        .m_doctypePubid
        .and_then(|public_id| parser.m_tempPool.chars_from(public_id));
    let doctype_sysid = match parser.m_doctypeSysid {
        DoctypeSystemId::Pool(system_id) => parser
            .m_tempPool
            .chars_from(system_id),
        DoctypeSystemId::None | DoctypeSystemId::ExternalSubset => None,
    };
    callback.invoke(StartDoctypeDeclCallbackEvent {
        parser,
        name: doctype_name,
        system_id: doctype_sysid,
        public_id: doctype_pubid,
        has_internal_subset,
    });
}

/// Dispatch an end-element callback from a self-contained, terminated name.
///
/// Content processing snapshots the name before a preceding callback can
/// re-enter and reuse the parser's tag or pool storage.  Keeping the foreign
/// call here leaves the token loop with ordinary Rust slices and a typed
/// callback registry entry.
fn dispatch_end_element_callback(
    callback: &dyn EndElementCallback,
    parser: &XML_ParserStruct,
    name: &[crate::expat_external_h::XML_Char],
) -> bool {
    // The safe callback representation is valid only for the documented
    // NUL-terminated name view prepared by the content processors.
    if name.last().copied() != Some(0) {
        return false;
    }
    let Some(callback) = (callback as &dyn std::any::Any).downcast_ref::<
        extern "C" fn(
            *mut ::core::ffi::c_void,
            *const crate::expat_external_h::XML_Char,
        ),
    >() else {
        return false;
    };
    callback(handler_arg_from_state!(parser), name.as_ptr());
    true
}

/// Invokes a registered CDATA boundary callback with the parser's current
/// handler context.  The callback registry is populated only through the C
/// handler setters, so parser logic can retain a typed parser reference until
/// this narrow ABI dispatch point.
fn invoke_cdata_section_callback(
    callback: &CdataSectionCallbackAdapter,
    parser: &XML_ParserStruct,
) {
    callback.invoke(parser)
}

trait NotStandaloneCallback: Send + Sync + std::any::Any {}

impl NotStandaloneCallback
    for unsafe extern "C" fn(*mut ::core::ffi::c_void) -> ::core::ffi::c_int
{
}

/// A not-standalone handler registration prepared from the ABI callback value.
///
/// Parser state records only whether a handler is installed; the callable
/// foreign callback remains in the boundary registry keyed by the opaque
/// parser address.
struct NotStandaloneHandlerRegistration {
    callback: Option<std::sync::Arc<dyn NotStandaloneCallback>>,
}

fn not_standalone_handler_registration<Callback>(
    handler: Option<Callback>,
) -> NotStandaloneHandlerRegistration
where
    Callback: NotStandaloneCallback + 'static,
{
    NotStandaloneHandlerRegistration {
        callback: handler.map(|callback| std::sync::Arc::new(callback) as _),
    }
}

/// Invokes the not-standalone callback after the parser has captured the
/// callback's typed view of its handler context.  Keeping the ABI call here
/// lets parser state machines report the event without directly invoking a
/// foreign callback.
fn dispatch_not_standalone_callback(
    callback: &dyn NotStandaloneCallback,
    parser: &XML_ParserStruct,
) -> ::core::ffi::c_int {
    let Some(callback) = (callback as &dyn std::any::Any).downcast_ref::<
        unsafe extern "C" fn(*mut ::core::ffi::c_void) -> ::core::ffi::c_int,
    >() else {
        return 0;
    };
    unsafe { callback(handler_arg_from_state!(parser)) }
}

// Foreign callback values remain in this boundary registry; parser state only
// records whether a not-standalone callback is installed.
static NOT_STANDALONE_HANDLERS: std::sync::OnceLock<
    std::sync::Mutex<std::collections::HashMap<usize, std::sync::Arc<dyn NotStandaloneCallback>>>,
> = std::sync::OnceLock::new();

fn set_not_standalone_handler(
    parser: &mut XML_ParserStruct,
    parser_address: usize,
    registration: NotStandaloneHandlerRegistration,
) {
    parser.m_notStandaloneHandler = registration.callback.is_some();
    let mut handlers = NOT_STANDALONE_HANDLERS
        .get_or_init(|| std::sync::Mutex::new(std::collections::HashMap::new()))
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner());
    match registration.callback {
        Some(callback) => {
            handlers.insert(parser_address, callback);
        }
        None => {
            handlers.remove(&parser_address);
        }
    }
}

/// Dispatches character data that is already held in typed Rust storage.
///
/// The parser key and callback context are derived from a live parser borrow,
/// while `data` supplies a checked length and a valid temporary callback view.
/// Keep the raw ABI call at this narrow boundary so content processing itself
/// does not need the legacy raw callback adapter.
fn dispatch_character_data_callback(
    callback: &CharacterDataCallbackAdapter,
    parser: &XML_ParserStruct,
    data: &[crate::expat_external_h::XML_Char],
) {
    callback.invoke(CharacterDataCallbackEvent { parser, data });
}

/// Invokes a processing-instruction callback with parser-owned snapshots.
/// The two strings are terminated XML-character vectors, and their storage
/// remains live through the callback.
fn dispatch_processing_instruction_callback(
    callback: &TwoXmlCharCallbackAdapter,
    parser: &XML_ParserStruct,
    target: &[crate::expat_external_h::XML_Char],
    data: &[crate::expat_external_h::XML_Char],
) {
    callback.invoke(TwoXmlCharCallbackEvent {
        parser,
        first: Some(target),
        second: Some(data),
    });
}

/// Invokes a comment callback with a terminated parser-owned snapshot.
fn dispatch_comment_callback(
    callback: &CommentCallbackAdapter,
    parser: &XML_ParserStruct,
    data: &[crate::expat_external_h::XML_Char],
) {
    callback.invoke(CommentCallbackInvocation { parser, data });
}

fn dispatch_character_data_slice(
    parser: &XML_ParserStruct,
    data: &[crate::expat_external_h::XML_Char],
) {
    let callback = CHARACTER_DATA_HANDLERS
        .get_or_init(|| std::sync::Mutex::new(std::collections::HashMap::new()))
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner())
        .get(&std::ptr::from_ref(parser).addr())
        .cloned();
    if let Some(callback) = callback {
        dispatch_character_data_callback(callback.as_ref(), parser, data);
    }
}

trait EntityDeclCallback: Send + Sync {
    unsafe fn invoke(
        &self,
        user_data: *mut ::core::ffi::c_void,
        entity_name: *const crate::expat_external_h::XML_Char,
        is_parameter_entity: ::core::ffi::c_int,
        value: *const crate::expat_external_h::XML_Char,
        value_length: ::core::ffi::c_int,
        base: *const crate::expat_external_h::XML_Char,
        system_id: *const crate::expat_external_h::XML_Char,
        public_id: *const crate::expat_external_h::XML_Char,
        notation_name: *const crate::expat_external_h::XML_Char,
    );
}

// Entity declaration callbacks are described with pool handles until the
// final ABI boundary.  This keeps the prolog state machine from assembling
// raw callback arguments while preserving the callback's transient views.
#[derive(Copy, Clone)]
enum EntityDeclValue {
    None,
    Internal {
        text: PoolStringRef,
        length: ::core::ffi::c_int,
    },
}

#[derive(Copy, Clone)]
struct EntityDeclCallbackEvent {
    name: PoolStringRef,
    is_parameter_entity: ::core::ffi::c_int,
    value: EntityDeclValue,
    base: Option<PoolStringRef>,
    system_id: Option<PoolStringRef>,
    public_id: Option<PoolStringRef>,
    notation: Option<PoolStringRef>,
}

fn entity_decl_handler(parser: &XML_ParserStruct) -> Option<std::sync::Arc<dyn EntityDeclCallback>> {
    ENTITY_DECL_HANDLERS
        .get_or_init(|| std::sync::Mutex::new(std::collections::HashMap::new()))
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner())
        .get(&std::ptr::from_ref(parser).addr())
        .cloned()
}

/// Dispatches a declaration from stable DTD pool handles.
///
/// The pool owns every identifier and internal replacement text through the
/// callback.  The raw ABI views are materialized only for this call, after
/// which callback re-entry cannot leave a prolog borrow outstanding.
fn dispatch_entity_decl_callback(
    callback: &dyn EntityDeclCallback,
    parser: &XML_ParserStruct,
    dtd: &DTD,
    event: EntityDeclCallbackEvent,
) {
    let name = dtd
        .pool
        .chars_from(event.name)
        .map_or(::core::ptr::null(), |chars| chars.as_ptr());
    let (value, value_length) = match event.value {
        EntityDeclValue::None => (::core::ptr::null(), 0),
        EntityDeclValue::Internal { text, length } => (
            dtd.entityValuePool
                .chars_from(text)
                .map_or(::core::ptr::null(), |chars| chars.as_ptr()),
            length,
        ),
    };
    let base = event
        .base
        .map_or(::core::ptr::null(), |base| {
            dtd.pool
                .chars_from(base)
                .map_or(::core::ptr::null(), |chars| chars.as_ptr())
        });
    let system_id = event.system_id.map_or(::core::ptr::null(), |system_id| {
        dtd.pool
            .chars_from(system_id)
            .map_or(::core::ptr::null(), |chars| chars.as_ptr())
    });
    let public_id = event.public_id.map_or(::core::ptr::null(), |public_id| {
        dtd.pool
            .chars_from(public_id)
            .map_or(::core::ptr::null(), |chars| chars.as_ptr())
    });
    let notation = event.notation.map_or(::core::ptr::null(), |notation| {
        dtd.pool
            .chars_from(notation)
            .map_or(::core::ptr::null(), |chars| chars.as_ptr())
    });
    unsafe {
        callback.invoke(
            handler_arg_from_state!(parser),
            name,
            event.is_parameter_entity,
            value,
            value_length,
            base,
            system_id,
            public_id,
            notation,
        );
    }
}

impl EntityDeclCallback
    for unsafe extern "C" fn(
        *mut ::core::ffi::c_void,
        *const crate::expat_external_h::XML_Char,
        ::core::ffi::c_int,
        *const crate::expat_external_h::XML_Char,
        ::core::ffi::c_int,
        *const crate::expat_external_h::XML_Char,
        *const crate::expat_external_h::XML_Char,
        *const crate::expat_external_h::XML_Char,
        *const crate::expat_external_h::XML_Char,
    )
{
    unsafe fn invoke(
        &self,
        user_data: *mut ::core::ffi::c_void,
        entity_name: *const crate::expat_external_h::XML_Char,
        is_parameter_entity: ::core::ffi::c_int,
        value: *const crate::expat_external_h::XML_Char,
        value_length: ::core::ffi::c_int,
        base: *const crate::expat_external_h::XML_Char,
        system_id: *const crate::expat_external_h::XML_Char,
        public_id: *const crate::expat_external_h::XML_Char,
        notation_name: *const crate::expat_external_h::XML_Char,
    ) {
        self(
            user_data,
            entity_name,
            is_parameter_entity,
            value,
            value_length,
            base,
            system_id,
            public_id,
            notation_name,
        );
    }
}

