pub struct HASH_TABLE {
    // The table owns a sized slot collection, so lookup and iteration can use
    // checked indexing instead of pointer arithmetic.  `backing` keeps the
    // corresponding allocation in the parser's configured memory suite.
    pub v: Option<HashTableSlots>,
    pub power: ::core::ffi::c_uchar,
    pub size: crate::__stddef_size_t_h::size_t,
    pub used: crate::__stddef_size_t_h::size_t,
    // This token retains the parser-specific allocation route without
    // retaining a dereferenceable parser back-pointer in the table.
    allocator: Option<HashTableAllocator>,
}

pub struct HashTableSlots {
    entries: Vec<Option<NamedAllocation>>,
    backing: Box<dyn FnMut(::core::ffi::c_int)>,
}

#[derive(Clone)]
struct HashTableAllocator {
    allocate: std::sync::Arc<
        dyn Fn(
            crate::__stddef_size_t_h::size_t,
            ::core::ffi::c_int,
        ) -> Option<Box<dyn FnMut(::core::ffi::c_int)>>,
    >,
}

impl HashTableAllocator {
    fn allocate(
        &self,
        size: crate::__stddef_size_t_h::size_t,
        source_line: ::core::ffi::c_int,
    ) -> Option<Box<dyn FnMut(::core::ffi::c_int)>> {
        (self.allocate)(size, source_line)
    }
}

struct NamedAllocation {
    // The table's lookup key is fixed when the record is created.  Retaining
    // it beside the typed record keeps key comparisons from having to reach
    // through the record's variant-specific owned allocation.
    key: PoolStringRef,
    record: NamedRecord,
    // Attribute identifiers are copied by all table clients.  Keep this
    // compact descriptor in the allocation itself instead of borrowing
    // through a separately boxed record.
    attribute_record: Option<ATTRIBUTE_ID>,
    backing: Box<dyn FnMut(::core::ffi::c_int)>,
}

// Hash tables contain only these four record kinds.  Keeping the owner typed
// means table clients that only need to inspect a record never have to
// reinterpret an allocation as a different Rust type.
enum NamedRecord {
    // Hash-table entries own each `NamedAllocation` directly.  Record access
    // is scoped to the table borrow, so these values do not need a separate
    // heap allocation for address stability.
    Prefix(PREFIX),
    Attribute,
    Element(ELEMENT_TYPE),
    // Entity records retain only pool handles, so moving a table entry during
    // a resize cannot invalidate data retained by the parser.
    Entity(ENTITY),
}

impl NamedRecord {
    fn new(create_size: usize, name: PoolStringRef) -> Option<(Self, Option<ATTRIBUTE_ID>)> {
        if create_size == ::core::mem::size_of::<PREFIX>() {
            return Some((Self::Prefix(PREFIX { name: Some(name) }), None));
        }
        if create_size == ::core::mem::size_of::<ATTRIBUTE_ID>() {
            return Some((Self::Attribute, Some(ATTRIBUTE_ID {
                named: NAMED { name },
                prefix: AttributePrefix::None,
                maybeTokenized: crate::expat_h::XML_FALSE,
                xmlns: crate::expat_h::XML_FALSE,
            })));
        }
        if create_size == ::core::mem::size_of::<ELEMENT_TYPE>() {
            return Some((Self::Element(ELEMENT_TYPE {
                named: NAMED { name },
                // This value is ignored until `hasPrefix` is set.  Use the
                // element's own valid pool handle rather than a zeroed,
                // invalid `PoolStringRef` placeholder.
                prefix: name,
                hasPrefix: crate::expat_h::XML_FALSE,
                idAtt: None,
                nDefaultAtts: 0,
                allocDefaultAtts: 0,
                defaultAtts: None,
            }), None));
        }
        if create_size == ::core::mem::size_of::<ENTITY>() {
            return Some((Self::Entity(ENTITY {
                named: NAMED { name },
                textPtr: EntityTextRef {
                    pool: EntityTextPool::Dtd,
                    string: None,
                },
                textLen: 0,
                processed: 0,
                systemId: None,
                base: None,
                publicId: None,
                notation: None,
                open: crate::expat_h::XML_FALSE,
                hasMore: crate::expat_h::XML_FALSE,
                is_param: crate::expat_h::XML_FALSE,
                is_internal: crate::expat_h::XML_FALSE,
            }), None));
        }
        None
    }
}

impl NamedAllocation {
    fn prefix(&self) -> Option<&PREFIX> {
        match &self.record {
            NamedRecord::Prefix(prefix) => Some(prefix),
            _ => None,
        }
    }

    fn attribute_snapshot(&self) -> Option<ATTRIBUTE_ID> {
        matches!(&self.record, NamedRecord::Attribute)
            .then_some(self.attribute_record)
            .flatten()
    }

    fn attribute_mut(&mut self) -> Option<&mut ATTRIBUTE_ID> {
        matches!(&self.record, NamedRecord::Attribute)
            .then_some(self.attribute_record.as_mut())
            .flatten()
    }

    fn element(&self) -> Option<&ELEMENT_TYPE> {
        match &self.record {
            NamedRecord::Element(element) => Some(element),
            _ => None,
        }
    }

    fn element_mut(&mut self) -> Option<&mut ELEMENT_TYPE> {
        match &mut self.record {
            NamedRecord::Element(element) => Some(element),
            _ => None,
        }
    }

    fn entity(&self) -> Option<ENTITY> {
        match &self.record {
            NamedRecord::Entity(entity) => Some(*entity),
            _ => None,
        }
    }
}

#[derive(Copy, Clone)]
#[repr(C)]

pub struct NAMED {
    // Every table key is retained in the DTD string pool.  Store its checked
    // pool location rather than an address into a growable slab; callers
    // materialize a pointer only at the operation that needs one.
    pub name: PoolStringRef,
}

pub type KEY = *const crate::expat_external_h::XML_Char;

pub type ATTRIBUTE_ID = attribute_id;
#[repr(C)]

pub struct ELEMENT_TYPE {
    // Element types live in the name table allocation, whose leading header
    // owns the pool-backed key.  Keeping that header here avoids a duplicate
    // pointer-bearing view of the same allocation while retaining the table's
    // layout and configured allocator.
    pub named: NAMED,
    // Prefix records are owned by the DTD prefix table.  Retain their
    // pool-backed name rather than an address into that table, so the link
    // remains allocator-neutral and can be resolved when needed.
    pub prefix: PoolStringRef,
    pub hasPrefix: crate::expat_h::XML_Bool,
    // The ID attribute is identified by its DTD-pool name.  The attribute
    // table may grow and move its slot array, whereas this pool location is
    // stable for the lifetime of the DTD and can be resolved when needed.
    pub idAtt: Option<PoolStringRef>,
    pub nDefaultAtts: ::core::ffi::c_int,
    pub allocDefaultAtts: ::core::ffi::c_int,
    // The records are owned values. Their opaque backing token preserves the
    // parser's configured malloc/realloc/free sequence without retaining a
    // dereferenceable allocation pointer in DTD state.
    defaultAtts: Option<DefaultAttributeStorage>,
}

struct DefaultAttributeStorage {
    values: Vec<DEFAULT_ATTRIBUTE>,
    backing: LiveParserAllocationBacking,
}
#[derive(Copy, Clone)]
#[repr(C)]

pub struct DEFAULT_ATTRIBUTE {
    // A default attribute names an identifier in the DTD attribute table.
    // Retain the identifier's pool-owned name, rather than an address into
    // that table: the handle stays valid across table growth and can be
    // resolved when the default is applied.
    //
    // This remains optional so an all-zero allocation representation is valid
    // until `defineAttribute` initializes the record.
    pub id: Option<PoolStringRef>,
    pub isCdata: crate::expat_h::XML_Bool,
    // Default values are terminated strings in the DTD pool.  Retain their
    // checked pool location rather than an address into allocator-owned
    // storage; this also remains valid if the pool grows.
    pub value: Option<PoolStringRef>,
}
#[derive(Copy, Clone)]
#[repr(C)]

pub struct ENTITY {
    // Hash-table records begin with their pool-backed key.  Reusing the
    // shared header keeps the hash-table view and entity view of this
    // allocator-owned allocation in sync without a second pointer field.
    pub named: NAMED,
    // Internal replacement text is a checked location in one of the DTD's
    // configured-allocator pools.  Its nullability continues to denote an
    // external entity without retaining an allocator-owned address.
    pub textPtr: EntityTextRef,
    pub textLen: ::core::ffi::c_int,
    pub processed: ::core::ffi::c_int,
    // System identifiers are owned by the DTD string pool.  Retain their
    // stable pool location instead of an address into allocator-managed
    // storage; callback adapters resolve it immediately before invocation.
    pub systemId: Option<PoolStringRef>,
    // A base identifier is nullable and, when present, is identified by its
    // stable location in the DTD string pool.  The address is recovered only
    // at callback boundaries, after checking that the pool block is live.
    pub base: Option<PoolStringRef>,
    // Public identifiers are normalized in, and owned by, the DTD pool.
    // Store a checked pool location instead of retaining its allocator-owned
    // address between callbacks.
    pub publicId: Option<PoolStringRef>,
    // Unparsed-entity notation names are committed to the DTD string pool.
    // Keep their stable pool location rather than retaining a raw address.
    pub notation: Option<PoolStringRef>,
    pub open: crate::expat_h::XML_Bool,
    pub hasMore: crate::expat_h::XML_Bool,
    pub is_param: crate::expat_h::XML_Bool,
    pub is_internal: crate::expat_h::XML_Bool,
}

fn entity_text_chars(
    dtd: &DTD,
    text: EntityTextRef,
    length: ::core::ffi::c_int,
) -> Option<&[crate::expat_external_h::XML_Char]> {
    let string = text.string?;
    match text.pool {
        EntityTextPool::Dtd => dtd.pool.chars_at(string, length),
        EntityTextPool::EntityValue => dtd.entityValuePool.chars_at(string, length),
    }
}

fn event_raw_name_storage(
    parser: &XML_ParserStruct,
    dtd: &DTD,
    parser_events: bool,
    address: usize,
) -> Option<RawNameStorage> {
    if parser_events {
        return Some(RawNameStorage::InputBuffer(
            parser.m_buffer.offset_from_address(address)?,
        ));
    }

    let open_entity = parser
        .m_openInternalEntities
        .and_then(|index| parser.m_activeInternalEntities.get(index))?
        .node();
    let text = entity_text_chars(dtd, open_entity.eventText, open_entity.eventTextLen)?;
    let offset = address
        .checked_sub(text.as_ptr().addr())
        .filter(|offset| *offset <= text.len())?;
    Some(RawNameStorage::EntityText {
        text: open_entity.eventText,
        length: open_entity.eventTextLen,
        offset,
    })
}

fn event_raw_name_source<'a>(
    parser: &'a XML_ParserStruct,
    dtd: &'a DTD,
    parser_events: bool,
    start: usize,
    end: usize,
) -> Option<RawNameSource<'a>> {
    if parser_events {
        return Some(RawNameSource::Bytes(
            parser.m_buffer.window_from_addresses(start, end)?,
        ));
    }

    let open_entity = parser
        .m_openInternalEntities
        .and_then(|index| parser.m_activeInternalEntities.get(index))?
        .node();
    let text = entity_text_chars(dtd, open_entity.eventText, open_entity.eventTextLen)?;
    let start = start.checked_sub(text.as_ptr().addr())?;
    let end = end.checked_sub(text.as_ptr().addr())?;
    Some(RawNameSource::Chars(text.get(start..end)?))
}

/// Resolves an entity-value token through the storage that owns its cursors.
///
/// Entity values can be scanned directly from the parser input or from the
/// replacement text of the current value entity.  In both cases the tokenizer
/// has already supplied a bounded token range; resolving that range here keeps
/// character-reference decoding from fabricating a slice out of raw cursors.
fn entity_value_token_source<'a>(
    parser: &'a XML_ParserStruct,
    dtd: &'a DTD,
    start: usize,
    end: usize,
) -> Option<RawNameSource<'a>> {
    if let Some(bytes) = parser.m_buffer.window_from_addresses(start, end) {
        return Some(RawNameSource::Bytes(bytes));
    }

    // Entity declarations can themselves occur while an internal entity is
    // being expanded.  Both stacks own immutable replacement text, so resolve
    // either cursor through its owning record before exposing a token slice.
    let entity = parser
        .m_openValueEntities
        .and_then(|index| parser.m_activeValueEntities.get(index))
        .map(InternalEntityStorage::node)
        .or_else(|| {
            parser
                .m_openInternalEntities
                .and_then(|index| parser.m_activeInternalEntities.get(index))
                .map(InternalEntityStorage::node)
        })?;
    let text = entity_text_chars(dtd, entity.eventText, entity.eventTextLen)?;
    let start = start.checked_sub(text.as_ptr().addr())?;
    let end = end.checked_sub(text.as_ptr().addr())?;
    Some(RawNameSource::Chars(text.get(start..end)?))
}

/// Resolves a complete start-tag token into the storage that owns both of its
/// cursors.  Parser-buffer events and internal-entity events deliberately use
/// different backing storage, so callers never derive a range from cursors
/// belonging to different allocations.
fn attribute_token_source<'a>(
    parser_events: bool,
    input: &'a InputBuffer,
    open_entity_index: Option<usize>,
    active_entities: &'a [InternalEntityStorage],
    dtd: &'a DTD,
    start_address: usize,
    end_address: usize,
) -> Option<crate::src::xmltok::AttributeSource<'a>> {
    if parser_events {
        return input
            .window_from_addresses(start_address, end_address)
            .map(crate::src::xmltok::AttributeSource::Bytes);
    }

    let open_entity = active_entities.get(open_entity_index?)?.node();
    let text = entity_text_chars(dtd, open_entity.eventText, open_entity.eventTextLen)?;
    let start = start_address.checked_sub(text.as_ptr().addr())?;
    let end = end_address.checked_sub(text.as_ptr().addr())?;
    (start <= end)
        .then(|| text.get(start..end))?
        .map(crate::src::xmltok::AttributeSource::Chars)
}

/// Name measurements that share a cursor-bounded event window.
struct EventNameMeasurement {
    length: ::core::ffi::c_int,
    whitespace_after_name: Option<usize>,
}

/// Measures a name from a token window that has already been validated
/// against its owning parser or entity storage.  A processing instruction may
/// additionally request the leading whitespace length before its trailing
/// delimiter.
fn measure_event_name(
    encoding: &crate::src::xmltok::ENCODING,
    normal_encoding: &crate::src::xmltok::normal_encoding,
    chars: &[::core::ffi::c_char],
    trailing_delimiter_width: Option<usize>,
) -> Option<EventNameMeasurement> {
    let length = encoding.nameLength.measure(
        normal_encoding,
        crate::src::xmltok::AttributeSource::Chars(chars),
    );
    let whitespace_after_name = trailing_delimiter_width.map(|trailing_width| {
        let name_end = usize::try_from(length).ok()?;
        let data_end = chars.len().checked_sub(trailing_width)?;
        let data = chars.get(name_end..data_end)?;
        Some(crate::src::xmltok::skip_s(data, encoding.skipS))
    }).flatten();
    Some(EventNameMeasurement {
        length,
        whitespace_after_name,
    })
}

fn stored_raw_name_source<'a>(
    parser: &'a XML_ParserStruct,
    dtd: &'a DTD,
    tag: &'a TAG,
) -> Option<RawNameSource<'a>> {
    let length = usize::try_from(tag.rawNameLength).ok()?;
    match tag.rawName {
        RawNameStorage::TagBuffer(offset) => Some(RawNameSource::Chars(
            tag.buffer.bytes.get(offset..offset.checked_add(length)?)?,
        )),
        storage => retained_raw_name_source(parser, dtd, storage, length),
    }
}

fn retained_raw_name_source<'a>(
    parser: &'a XML_ParserStruct,
    dtd: &'a DTD,
    storage: RawNameStorage,
    length: usize,
) -> Option<RawNameSource<'a>> {
    match storage {
        RawNameStorage::Unset => None,
        RawNameStorage::InputBuffer(offset) => Some(RawNameSource::Bytes(
            parser
                .m_buffer
                .bytes
                .as_deref()?
                .get(offset..offset.checked_add(length)?)?,
        )),
        RawNameStorage::EntityText {
            text,
            length: text_length,
            offset,
        } => Some(RawNameSource::Chars(
            entity_text_chars(dtd, text, text_length)?.get(offset..offset.checked_add(length)?)?,
        )),
        RawNameStorage::TagBuffer(_) => None,
    }
}

// Resolve shared replacement text through the owning facade and copy it
// before returning.  The caller cannot retain a slice into a DTD that a
// callback may later grow or relocate.
fn shared_entity_text_chars(
    dtd: &SharedDtd,
    text: EntityTextRef,
    length: ::core::ffi::c_int,
) -> Option<Vec<crate::expat_external_h::XML_Char>> {
    dtd.inspect(|dtd| entity_text_chars(dtd, text, length).map(ToOwned::to_owned))
}

// Internal-entity events are locations in the entity's replacement text, not
// addresses into its growable pool.  This representation remains valid when a
// callback grows that pool and moves its backing allocation.
fn internal_event_offset(window: Option<(usize, usize)>, address: usize) -> Option<usize> {
    let (start, len) = window?;
    address.checked_sub(start).filter(|offset| *offset <= len)
}

fn event_text_window(dtd: &DTD, entity: &OPEN_INTERNAL_ENTITY) -> Option<(usize, usize)> {
    let text = entity_text_chars(dtd, entity.eventText, entity.eventTextLen)?;
    Some((text.as_ptr().addr(), text.len()))
}

pub type OPEN_INTERNAL_ENTITY = open_internal_entity;
#[derive(Copy, Clone)]
