#[derive(Copy, Clone)]
struct ExpatReallocationChange {
    is_increase: bool,
    absolute_difference: crate::__stddef_size_t_h::size_t,
}

fn expat_reallocation_change(
    size: crate::__stddef_size_t_h::size_t,
    previous_size: crate::__stddef_size_t_h::size_t,
) -> ExpatReallocationChange {
    if size > previous_size {
        ExpatReallocationChange {
            is_increase: true,
            absolute_difference: size.wrapping_sub(previous_size),
        }
    } else {
        ExpatReallocationChange {
            is_increase: false,
            absolute_difference: previous_size.wrapping_sub(size),
        }
    }
}

/// Applies the allocation-accounting portion of a successful reallocation.
///
/// The allocator callback has already completed when this runs, so this only
/// updates parser-owned tracking state and determines whether diagnostics are
/// required.  Keeping that work free of allocation addresses prevents the
/// accounting path from depending on the foreign allocation layout.
fn expat_apply_reallocation_tracking(
    root: &std::sync::Arc<std::sync::Mutex<RootParserState>>,
    change: ExpatReallocationChange,
    previous_payload_address: usize,
    new_payload_address: usize,
    new_payload_size: crate::__stddef_size_t_h::size_t,
) -> Option<(XmlBigCount, XmlBigCount)> {
    let mut root = root
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner());
    root.allocations.remove(&previous_payload_address);
    root.allocations.insert(
        new_payload_address,
        ExpatAllocation {
            payload_size: new_payload_size,
        },
    );
    if change.is_increase {
        assert!(
            (-1 as ::core::ffi::c_int as XmlBigCount)
                .wrapping_sub(root.alloc_tracker.bytesAllocated)
                >= change.absolute_difference as XmlBigCount
        );
        root.alloc_tracker.bytesAllocated = root
            .alloc_tracker
            .bytesAllocated
            .wrapping_add(change.absolute_difference as XmlBigCount);
    } else {
        assert!(root.alloc_tracker.bytesAllocated >= change.absolute_difference as XmlBigCount);
        root.alloc_tracker.bytesAllocated = root
            .alloc_tracker
            .bytesAllocated
            .wrapping_sub(change.absolute_difference as XmlBigCount);
    }
    if root.alloc_tracker.debugLevel >= 2 as ::core::ffi::c_ulong {
        if root.alloc_tracker.bytesAllocated > root.alloc_tracker.peakBytesAllocated {
            root.alloc_tracker.peakBytesAllocated = root.alloc_tracker.bytesAllocated;
        }
        Some((
            root.alloc_tracker.bytesAllocated,
            root.alloc_tracker.peakBytesAllocated,
        ))
    } else {
        None
    }
}

/// Internal allocator implementation behind the exported `expat_realloc`
/// boundary.  It deliberately keeps the assertion and allocator interaction
/// out of `expat_realloc_ffi`, whose only job is to dispatch the ABI call.
fn expat_realloc_missing_parser() -> ! {
    assert!(false, "parser != NULL");
    unreachable!()
}

fn expat_realloc(
    root: &std::sync::Arc<std::sync::Mutex<RootParserState>>,
    factory: Option<&AllocationBackingFactory>,
    payload_address: usize,
    size: crate::__stddef_size_t_h::size_t,
    source_line: ::core::ffi::c_int,
) -> usize {
    if payload_address == 0 {
        let Some(mut allocation) =
            new_test_visible_allocation_with_factory(factory, size, source_line)
        else {
            return 0;
        };
        let payload_address = allocation
            .storage
            .chunks
            .as_mut_ptr()
            .cast::<u8>()
            .wrapping_add(TestAllocationStorage::payload_offset())
            .addr();
        root
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner())
            .test_allocations
            .insert(payload_address, allocation);
        return payload_address;
    }
    if size == 0 as crate::__stddef_size_t_h::size_t {
        let mut allocation = root
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner())
            .test_allocations
            .remove(&payload_address)
            .expect("expat allocation must be tracked");
        allocation
            .backing
            .apply(ParserAllocationAction::Free(source_line));
        return 0;
    }
    assert!(
        (18446744073709551615 as usize)
            .wrapping_sub(::core::mem::size_of::<crate::__stddef_size_t_h::size_t>())
            .wrapping_sub(
                ::core::mem::size_of::<::core::ffi::c_longlong>()
                    .wrapping_sub(::core::mem::size_of::<crate::__stddef_size_t_h::size_t>()),
            )
            >= size,
        "SIZE_MAX - sizeof(size_t) - EXPAT_MALLOC_PADDING >= size"
    );
    let Some(replacement_storage) = TestAllocationStorage::new(size) else {
        return 0;
    };
    let mut allocation = root
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner())
        .test_allocations
        .remove(&payload_address)
        .expect("expat allocation must be tracked");
    if !allocation.backing.apply(ParserAllocationAction::Grow {
        size,
        source_line,
    }) {
        root.lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner())
            .test_allocations
            .insert(payload_address, allocation);
        return 0;
    }
    allocation.storage = replacement_storage;
    let new_payload_address = allocation
        .storage
        .chunks
        .as_mut_ptr()
        .cast::<u8>()
        .wrapping_add(TestAllocationStorage::payload_offset())
        .addr();
    root.lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner())
        .test_allocations
        .insert(new_payload_address, allocation);
    new_payload_address
}

/// Captures the parser-owned allocator route before the address-only
/// reallocation implementation runs.  The route contains no parser handle,
/// so the allocation bookkeeping stays outside the ABI wrapper.
fn expat_realloc_for_parser(
    parser: &mut XML_ParserStruct,
    payload_address: usize,
    size: crate::__stddef_size_t_h::size_t,
    source_line: ::core::ffi::c_int,
) -> usize {
    let root = parser.m_root.clone();
    let factory = parser.m_allocationBackingFactory.clone();
    expat_realloc(&root, factory.as_ref(), payload_address, size, source_line)
}

