fn ENTROPY_DEBUG(label: &str, entropy: ::core::ffi::c_ulong) -> ::core::ffi::c_ulong {
    if environment_decimal_debug_level("EXPAT_ENTROPY_DEBUG", 0) >= 1 {
        use std::io::Write;

        let hex_width = ::core::mem::size_of::<::core::ffi::c_ulong>() * 2;
        let byte_count = ::core::mem::size_of::<::core::ffi::c_ulong>();
        // Debug output must not affect parser initialization, matching the
        // ignored `fprintf` result in the C implementation.
        let _ = writeln!(
            std::io::stderr().lock(),
            "expat: Entropy: {label} --> 0x{entropy:0hex_width$x} ({byte_count} bytes)"
        );
    }
    entropy
}

/// Produces the process-local hash salt without exposing temporary entropy
/// storage to the C ABI.  Expat's original `arc4random_buf` path cannot
/// report failure, so an unavailable operating-system entropy source is a
/// non-recoverable initialization failure as well.
fn generate_hash_secret_salt() -> ::core::ffi::c_ulong {
    let mut entropy: ::core::ffi::c_ulong = 0;
    if getrandom::fill(bytemuck::bytes_of_mut(&mut entropy)).is_err() {
        std::process::abort();
    }
    return ENTROPY_DEBUG("arc4random_buf", entropy);
}

fn get_hash_secret_salt(
    root: &std::sync::Mutex<RootParserState>,
) -> ::core::ffi::c_ulong {
    root
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner())
        .hash_secret_salt
}

#[derive(Copy, Clone)]
struct ProcessorInput {
    start: usize,
    end: usize,
}

/// Runs the parser's current processor against a checked input range.
///
/// The parser can call user handlers while a processor runs, so every parser
/// reference below is scoped to the state inspection or update that needs it.
/// In particular, no `&mut XML_ParserStruct` survives the processor call.
struct ProcessorCall<'a> {
    parser: &'a mut XML_ParserStruct,
    input: ProcessorInput,
}

fn call_processor_dispatch(
    ProcessorCall { parser, input }: ProcessorCall<'_>,
) -> (crate::expat_h::XML_Error, usize) {
    let Some(have_now) = input.end.checked_sub(input.start) else {
        return (crate::expat_h::XML_ERROR_UNEXPECTED_STATE, input.start);
    };
    if parser
        .m_buffer
        .bytes
        .as_ref()
        .is_none_or(|bytes| input.end > bytes.len())
    {
        return (crate::expat_h::XML_ERROR_UNEXPECTED_STATE, input.start);
    }
    let have_now = have_now as crate::__stddef_size_t_h::size_t;
    {
        if parser.m_reparseDeferralEnabled as ::core::ffi::c_int != 0
            && parser.m_parsingStatus.finalBuffer == 0
        {
            let had_before = parser.m_partialTokenBytesBefore;
            let mut available_buffer = parser.m_bufferPtr.unwrap_or(0)
                as crate::__stddef_size_t_h::size_t;
            available_buffer = available_buffer.wrapping_sub(available_buffer.min(1024));
            available_buffer = available_buffer.wrapping_add(
                parser
                    .m_buffer
                    .bytes
                    .as_ref()
                    .map_or(0, |bytes| bytes.len().saturating_sub(parser.m_bufferEnd))
                    as crate::__stddef_size_t_h::size_t,
            );
            let enough = have_now >= 2usize.wrapping_mul(had_before)
                || parser.m_lastBufferRequestSize as crate::__stddef_size_t_h::size_t
                    > available_buffer;
            if !enough {
                return (crate::expat_h::XML_ERROR_NONE, input.start);
            }
        }
    }
    g_bytesScanned.fetch_add(
        have_now as ::core::ffi::c_uint,
        std::sync::atomic::Ordering::Relaxed,
    );
    let mut next = input.start;
    let mut ret = crate::expat_h::XML_ERROR_NONE;
    loop {
        // `PrologInit` only selects the tokenizer encoding before running the
        // ordinary prolog processor over this same checked input window.
        // Keep that state transition in the checked dispatcher instead of
        // reconstructing raw cursors in a separate processor adapter.
        if matches!(parser.m_processor, ProcessorState::PrologInit) {
            let result = initialize_encoding_impl(parser);
            if result as ::core::ffi::c_uint
                != crate::expat_h::XML_ERROR_NONE as ::core::ffi::c_int as ::core::ffi::c_uint
            {
                return (result, next);
            }
            parser.m_processor = ProcessorState::Prolog;
        }
        // External-entity initialization has the same checked encoding setup
        // as the prolog initializer.  Its former raw adapter only performed
        // this state change before tail-calling the ordinary second-stage
        // processor, so make the transition before raw cursor dispatch.
        if matches!(parser.m_processor, ProcessorState::ExternalEntityInit) {
            let result = initialize_encoding_impl(parser);
            if result as ::core::ffi::c_uint
                != crate::expat_h::XML_ERROR_NONE as ::core::ffi::c_int as ::core::ffi::c_uint
            {
                return (result, next);
            }
            parser.m_processor = ProcessorState::ExternalEntityInit2;
        }
        let Some(bytes) = parser.m_buffer.bytes.as_ref() else {
            return (crate::expat_h::XML_ERROR_UNEXPECTED_STATE, next);
        };
        if next > input.end || input.end > bytes.len() {
            return (crate::expat_h::XML_ERROR_UNEXPECTED_STATE, next);
        }
        // CDATA cursor results are already checked buffer offsets.  Keep
        // them as offsets through this dispatch instead of rebuilding a raw
        // cursor merely for the common processor epilogue below.
        let mut checked_next_offset = None;
        ret = if matches!(parser.m_processor, ProcessorState::CdataSection) {
            let result = cdata_section_processor_impl(parser, next, input.end);
            checked_next_offset = Some(result.next_offset);
            result.error
        } else if matches!(parser.m_processor, ProcessorState::Epilog) {
            // The epilog implementation is offset-based, so it can consume
            // this already-validated live-buffer range without reconstructing
            // the legacy raw processor cursors.
            let result = epilog_processor_from_offsets(parser, next, input.end);
            if let Some(cursor) = result.next {
                let Some(offset) = next
                    .checked_add(cursor)
                    .filter(|offset| *offset <= input.end)
                else {
                    return (crate::expat_h::XML_ERROR_UNEXPECTED_STATE, next);
                };
                checked_next_offset = Some(offset);
            }
            result.error
        } else if matches!(parser.m_processor, ProcessorState::IgnoreSection) {
            // Ignore-section scanning is already expressed in terms of the
            // parser-owned input window.  Keep its cursor as an offset here,
            // rather than reconstructing the legacy C processor arguments.
            let Some(start_address) = parser.m_buffer.address_at_offset(next) else {
                return (crate::expat_h::XML_ERROR_UNEXPECTED_STATE, next);
            };
            let Some(end_address) = parser.m_buffer.address_at_offset(input.end) else {
                return (crate::expat_h::XML_ERROR_UNEXPECTED_STATE, next);
            };
            let result = ignore_section_processor_impl(parser, start_address, end_address);
            let ignore_next = result.next_offset.map(|offset| {
                next.checked_add(offset)
                    .filter(|offset| *offset <= input.end)
            });
            if ignore_next.is_some_and(|offset| offset.is_none()) {
                return (crate::expat_h::XML_ERROR_UNEXPECTED_STATE, next);
            }
            // A default handler may re-enter and relocate the input buffer.
            // Validate the returned logical cursor against that live buffer
            // before either returning it or passing it into prolog handling.
            if ignore_next.flatten().is_some_and(|offset| {
                parser.m_buffer.window_from_offsets(offset, offset).is_none()
            })
            {
                return (crate::expat_h::XML_ERROR_UNEXPECTED_STATE, next);
            }
            if result.error as ::core::ffi::c_uint
                != crate::expat_h::XML_ERROR_NONE as ::core::ffi::c_int as ::core::ffi::c_uint
            {
                checked_next_offset = Some(ignore_next.flatten().unwrap_or(next));
                result.error
            } else if let Some(prolog_relative_start) = result.prolog_start_offset {
                let Some(prolog_start) = next
                    .checked_add(prolog_relative_start)
                    .filter(|offset| *offset <= input.end)
                    .filter(|offset| {
                        parser
                            .m_buffer
                            .window_from_offsets(*offset, input.end)
                            .is_some()
                    })
                else {
                    return (crate::expat_h::XML_ERROR_UNEXPECTED_STATE, next);
                };
                let prolog = prolog_processor_from_offsets(parser, prolog_start, input.end);
                match prolog.cursor {
                    PrologCursorUpdate::Unchanged => {
                        checked_next_offset = Some(prolog_start);
                    }
                    PrologCursorUpdate::Cursor(Some(offset)) => {
                        if parser.m_buffer.window_from_offsets(offset, offset).is_none() {
                            return (crate::expat_h::XML_ERROR_UNEXPECTED_STATE, next);
                        }
                        checked_next_offset = Some(offset);
                    }
                    PrologCursorUpdate::Cursor(None) => {
                        return (crate::expat_h::XML_ERROR_UNEXPECTED_STATE, next);
                    }
                }
                prolog.error
            } else {
                checked_next_offset = Some(ignore_next.flatten().unwrap_or(next));
                result.error
            }
        } else if matches!(parser.m_processor, ProcessorState::ExternalEntityInit2) {
            // Keep both initialization scans on a stable snapshot, while
            // passing the corresponding live-buffer address to the state
            // transitions.  An XML declaration callback may relocate the
            // parser buffer, so no borrow of that buffer survives either
            // transition.
            let Some(source) = parser
                .m_buffer
                .bytes
                .as_ref()
                .and_then(|bytes| bytes.get(next..input.end))
                .map(ToOwned::to_owned)
            else {
                return (crate::expat_h::XML_ERROR_UNEXPECTED_STATE, next);
            };
            let source_chars: &[::core::ffi::c_char] = bytemuck::cast_slice(&source);
            let Some(start_address) = parser.m_buffer.address_at_offset(next) else {
                return (crate::expat_h::XML_ERROR_UNEXPECTED_STATE, next);
            };
            match external_entity_init_processor2_impl(parser, source_chars, start_address) {
                ExternalEntityInit2Action::Return(error, offset) => {
                    let Some(offset) = next
                        .checked_add(offset)
                        .filter(|offset| *offset <= input.end)
                    else {
                        return (crate::expat_h::XML_ERROR_UNEXPECTED_STATE, next);
                    };
                    checked_next_offset = Some(offset);
                    error
                }
                ExternalEntityInit2Action::Abort(error) => {
                    checked_next_offset = Some(next);
                    error
                }
                ExternalEntityInit2Action::Continue(first_offset) => {
                    let Some(remaining) = source_chars.get(first_offset..) else {
                        return (crate::expat_h::XML_ERROR_UNEXPECTED_STATE, next);
                    };
                    let Some(scan) = external_entity_init_scan(parser, remaining) else {
                        return (crate::expat_h::XML_ERROR_UNEXPECTED_STATE, next);
                    };
                    match external_entity_init_processor3_transition(
                        parser,
                        scan,
                        match start_address.checked_add(first_offset) {
                            Some(address) => address,
                            None => {
                                return (crate::expat_h::XML_ERROR_UNEXPECTED_STATE, next);
                            }
                        },
                        remaining.len(),
                    ) {
                        ExternalEntityInit3Action::Return(error, second_offset) => {
                            let Some(offset) = first_offset
                                .checked_add(second_offset)
                                .and_then(|offset| next.checked_add(offset))
                                .filter(|offset| *offset <= input.end)
                            else {
                                return (crate::expat_h::XML_ERROR_UNEXPECTED_STATE, next);
                            };
                            checked_next_offset = Some(offset);
                            error
                        }
                        ExternalEntityInit3Action::ContinueContent(second_offset) => {
                            let Some(content_relative_offset) = first_offset
                                .checked_add(second_offset)
                                .filter(|offset| *offset <= source_chars.len())
                            else {
                                return (crate::expat_h::XML_ERROR_UNEXPECTED_STATE, next);
                            };
                            let Some(content_offset) = next
                                .checked_add(content_relative_offset)
                                .filter(|offset| *offset <= input.end)
                            else {
                                return (crate::expat_h::XML_ERROR_UNEXPECTED_STATE, next);
                            };
                            // Resume through the existing external-content
                            // processor on the next checked dispatch.  That
                            // processor owns its legacy cursor boundary and
                            // preserves its post-content raw-name handling.
                            parser.m_processor = ProcessorState::ExternalEntityContent;
                            next = content_offset;
                            continue;
                        }
                    }
                }
            }
        } else if matches!(parser.m_processor, ProcessorState::ExternalEntityInit3) {
            // The current dispatch range has already been checked against
            // the live parser buffer.  Snapshot it before the state
            // transition, because processing an XML declaration may invoke a
            // callback that re-enters and relocates that buffer.
            let Some(source) = parser
                .m_buffer
                .bytes
                .as_ref()
                .and_then(|bytes| bytes.get(next..input.end))
                .map(ToOwned::to_owned)
            else {
                return (crate::expat_h::XML_ERROR_UNEXPECTED_STATE, next);
            };
            let source_chars: &[::core::ffi::c_char] = bytemuck::cast_slice(&source);
            let Some(scan) = external_entity_init_scan(parser, source_chars) else {
                return (crate::expat_h::XML_ERROR_UNEXPECTED_STATE, next);
            };
            let Some(start_address) = parser.m_buffer.address_at_offset(next) else {
                return (crate::expat_h::XML_ERROR_UNEXPECTED_STATE, next);
            };
            match external_entity_init_processor3_transition(
                parser,
                scan,
                start_address,
                source_chars.len(),
            ) {
                ExternalEntityInit3Action::Return(error, offset) => {
                    let Some(offset) = next
                        .checked_add(offset)
                        .filter(|offset| *offset <= input.end)
                    else {
                        return (crate::expat_h::XML_ERROR_UNEXPECTED_STATE, next);
                    };
                    checked_next_offset = Some(offset);
                    error
                }
                ExternalEntityInit3Action::ContinueContent(offset) => {
                    let Some(content_offset) = next
                        .checked_add(offset)
                        .filter(|offset| *offset <= input.end)
                    else {
                        return (crate::expat_h::XML_ERROR_UNEXPECTED_STATE, next);
                    };
                    // As above, continue through the dedicated external
                    // content processor so the checked dispatcher does not
                    // need a second safe-to-legacy content adapter.
                    parser.m_processor = ProcessorState::ExternalEntityContent;
                    next = content_offset;
                    continue;
                }
            }
        } else if matches!(
            parser.m_processor,
            ProcessorState::Content | ProcessorState::ExternalEntityContent
        ) {
            // Content processing is offset-based at this dispatcher boundary.
            // Keep its legacy cursor loop inside the implementation and
            // immediately re-check the returned cursor against the live
            // parser buffer after callbacks have had a chance to re-enter.
            let (error, content_next) =
                external_entity_content_processor_impl(parser, next, input.end);
            checked_next_offset = Some(content_next);
            error
        } else if matches!(parser.m_processor, ProcessorState::InternalEntity) {
            // Internal-entity expansion has no caller-buffer cursor: it
            // operates on the DTD-owned replacement text selected by the
            // active entity record.  Dispatch it directly from this checked
            // state machine instead of rebuilding the legacy raw processor
            // arguments solely to discard them in `internalEntityProcessor`.
            // It never consumes the caller's buffer, so retain its checked
            // offset rather than later validating an address that a callback
            // may have invalidated by relocating that buffer.
            checked_next_offset = Some(next);
            internal_entity_processor_impl(InternalEntityProcessorState { parser })
        } else if matches!(parser.m_processor, ProcessorState::Error) {
            // The error processor never consumes input or changes the cursor:
            // it only returns the parser's stored error.  Keep that terminal
            // state in the checked dispatcher instead of rebuilding a raw
            // parser handle and cursor solely for this read.
            parser.m_errorCode
        } else {
            // These transitions all have offset-based implementations.  Do
            // not round-trip through their legacy raw-cursor adapters merely
            // to immediately translate the returned cursor back to an
            // offset in this dispatcher.
            match parser.m_processor {
                ProcessorState::ExternalParEntInit => {
                    match external_par_ent_init_processor_impl(parser) {
                        Err(error) => error,
                        Ok(ExternalParEntInitAction::EntityValue) => {
                            let result = entity_value_init_processor_safe(EntityValueProcessorState {
                                parser,
                                value_start_offset: next,
                                end_offset: input.end,
                                output_next: None,
                            });
                            checked_next_offset = result.next_offset;
                            result.error
                        }
                        Ok(ExternalParEntInitAction::ExternalParameterEntity) => {
                            let result = external_par_ent_processor_impl(parser, next, input.end);
                            if let PrologCursorUpdate::Cursor(cursor) = result.cursor {
                                let Some(cursor) = cursor else {
                                    return (crate::expat_h::XML_ERROR_UNEXPECTED_STATE, next);
                                };
                                checked_next_offset = Some(cursor);
                            }
                            result.error
                        }
                    }
                }
                ProcessorState::ExternalParEnt => {
                    let result = external_par_ent_processor_impl(parser, next, input.end);
                    if let PrologCursorUpdate::Cursor(cursor) = result.cursor {
                        let Some(cursor) = cursor else {
                            return (crate::expat_h::XML_ERROR_UNEXPECTED_STATE, next);
                        };
                        checked_next_offset = Some(cursor);
                    }
                    result.error
                }
                ProcessorState::EntityValueInit => {
                    let result = entity_value_init_processor_safe(EntityValueProcessorState {
                        parser,
                        value_start_offset: next,
                        end_offset: input.end,
                        output_next: None,
                    });
                    checked_next_offset = result.next_offset;
                    result.error
                }
                ProcessorState::EntityValue => {
                    let result = entity_value_processor_safe(EntityValueProcessorState {
                        parser,
                        value_start_offset: next,
                        end_offset: input.end,
                        output_next: None,
                    });
                    checked_next_offset = result.next_offset;
                    result.error
                }
                ProcessorState::Prolog => {
                    let result = prolog_processor_from_offsets(parser, next, input.end);
                    if let PrologCursorUpdate::Cursor(cursor) = result.cursor {
                        let Some(cursor) = cursor else {
                            return (crate::expat_h::XML_ERROR_UNEXPECTED_STATE, next);
                        };
                        checked_next_offset = Some(cursor);
                    }
                    result.error
                }
                ProcessorState::PrologInit
                | ProcessorState::Content
                | ProcessorState::ExternalEntityInit
                | ProcessorState::ExternalEntityInit2
                | ProcessorState::ExternalEntityInit3
                | ProcessorState::ExternalEntityContent
                | ProcessorState::CdataSection
                | ProcessorState::IgnoreSection
                | ProcessorState::Epilog
                | ProcessorState::InternalEntity
                | ProcessorState::Error => {
                    unreachable!("this processor state is dispatched before the offset transition")
                }
            }
        };
        let next_offset = match checked_next_offset {
            Some(offset) => offset,
            None => next,
        };
        if next_offset > input.end
            || parser
                .m_buffer
                .window_from_offsets(next_offset, next_offset)
                .is_none()
        {
            return (crate::expat_h::XML_ERROR_UNEXPECTED_STATE, next);
        }
        next = next_offset;
        let reenter = {
            if parser.m_parsingStatus.parsing as ::core::ffi::c_uint
                != crate::expat_h::XML_PARSING as ::core::ffi::c_int as ::core::ffi::c_uint
            {
                parser.m_reenter = crate::expat_h::XML_FALSE;
            }
            if parser.m_reenter == 0 {
                false
            } else {
                parser.m_reenter = crate::expat_h::XML_FALSE;
                true
            }
        };
        let resume_after_cdata = std::mem::take(&mut parser.m_resumeAfterCdata);
        if !reenter && !resume_after_cdata {
            break;
        }
        if ret as ::core::ffi::c_uint
            != crate::expat_h::XML_ERROR_NONE as ::core::ffi::c_int as ::core::ffi::c_uint
        {
            return (ret, next);
        }
    }
    if ret as ::core::ffi::c_uint
        == crate::expat_h::XML_ERROR_NONE as ::core::ffi::c_int as ::core::ffi::c_uint
    {
        parser.m_partialTokenBytesBefore = if next == input.start {
            have_now
        } else {
            0
        };
    }
    (ret, next)
}

fn parser_create_mm(request: ParserCreationRequest<'_>) -> Option<Box<XML_ParserStruct>> {
    parser_create_ownership(request)
}
#[export_name = "XML_ParserCreate_MM"]

pub unsafe extern "C" fn XML_ParserCreate_MM_ffi(
    mut encodingName: *const crate::expat_external_h::XML_Char,
    mut memsuite: *const crate::expat_h::XML_Memory_Handling_Suite,
    mut nameSep: *const crate::expat_external_h::XML_Char,
) -> crate::expat_h::XML_Parser {
    let encoding_name = (!encodingName.is_null()).then(|| std::ffi::CStr::from_ptr(encodingName));
    let memory_suite = memsuite.as_ref().copied().unwrap_or(
        crate::expat_h::XML_Memory_Handling_Suite {
            malloc_fcn: Some(crate::stdlib::malloc),
            realloc_fcn: Some(crate::stdlib::realloc),
            free_fcn: Some(crate::stdlib::free),
        },
    );
    parser_create_mm(ParserCreationRequest {
        encoding_name,
        memory_suite,
        namespace_separator: nameSep.as_ref().copied(),
        share_parent_dtd: false,
        parent: None,
    })
        .map_or_else(::core::ptr::null_mut, Box::into_raw)
}

struct ParserParentState {
    root: std::sync::Arc<std::sync::Mutex<RootParserState>>,
    depth: Option<::core::num::NonZeroU32>,
    inherited_dtd: Option<std::sync::Arc<SharedDtd>>,
}

/// The fully validated inputs for the Rust-owned parser construction path.
/// Raw C handles are converted before reaching this request.
struct ParserCreationRequest<'a> {
    encoding_name: Option<&'a std::ffi::CStr>,
    memory_suite: crate::expat_h::XML_Memory_Handling_Suite,
    namespace_separator: Option<crate::expat_external_h::XML_Char>,
    share_parent_dtd: bool,
    parent: Option<&'a XML_ParserStruct>,
}

/// Construct a parser through the single allocator-aware ownership boundary.
///
/// Parser storage keeps the same physical prefix as `expat_malloc`
/// allocations, so custom allocators observe the same requested size. Its
/// payload size is registered with the root state immediately after
/// construction, rather than being read from an in-band raw-memory header
/// during release. The first mutable access to the new allocation is kept
/// here, while it remains wholly owned by this allocation boundary.
fn parser_create_ownership(
    request: ParserCreationRequest<'_>,
) -> Option<Box<XML_ParserStruct>> {
    let ParserCreationRequest {
        encoding_name,
        memory_suite,
        namespace_separator,
        share_parent_dtd,
        parent,
    } = request;
    let increase = ::core::mem::size_of::<crate::__stddef_size_t_h::size_t>()
        .wrapping_add(crate::internal_h::EXPAT_MALLOC_PADDING)
        .wrapping_add(::core::mem::size_of::<XML_ParserStruct>());
    // Snapshot the parent before allocating the child so an allocator callback
    // cannot retain a borrow of the opaque parent parser.
    let parent_state = if let Some(parent) = parent {
        if !expat_heap_increase_tolerable(
            &parent.m_root,
            std::ptr::from_ref(parent).addr(),
            increase as XmlBigCount,
            1354 as ::core::ffi::c_int,
        ) {
            return None;
        }
        let inherited_dtd = if share_parent_dtd {
            let Some(dtd) = parent.m_dtd.as_ref() else {
                return None;
            };
            Some(std::sync::Arc::clone(dtd))
        } else {
            None
        };
        Some(ParserParentState {
            root: std::sync::Arc::clone(&parent.m_root),
            depth: parent.m_parentParser,
            inherited_dtd,
        })
    } else {
        None
    };
    if share_parent_dtd && parent_state.is_none() {
        return None;
    }
    let mut parser_owner = Box::pin(initial_parser_struct());
    let parser_ptr = std::ptr::from_mut(parser_owner.as_mut().get_mut());
    let Some(storage_backing) = parser_storage_backing(memory_suite) else {
        return None;
    };
    let parser = parser_owner.as_mut().get_mut();
    parser.m_parserStorageBacking = Some(storage_backing);
    parser.m_allocatorKey = parent
        .map(|parent| parent.m_allocatorKey)
        .unwrap_or_else(|| parser_ptr.addr());
    if parent.is_none() {
        register_allocator_suite(parser.m_allocatorKey, memory_suite);
    }
    let root_owner = {
        let alloc_tracker = MALLOC_TRACKER {
            bytesAllocated: 0 as XmlBigCount,
            peakBytesAllocated: 0 as XmlBigCount,
            debugLevel: if parent.is_none() {
                environment_decimal_debug_level("EXPAT_MALLOC_DEBUG", 0)
            } else {
                0 as ::core::ffi::c_ulong
            },
            maximumAmplificationFactor: if parent.is_none() {
                crate::internal_h::EXPAT_ALLOC_TRACKER_MAXIMUM_AMPLIFICATION_DEFAULT
            } else {
                0.0
            },
            activationThresholdBytes: if parent.is_none() {
                crate::internal_h::EXPAT_ALLOC_TRACKER_ACTIVATION_THRESHOLD_DEFAULT as XmlBigCount
            } else {
                0 as XmlBigCount
            },
        };
        if let Some(parent_state) = parent_state.as_ref() {
            parser.m_root = std::sync::Arc::clone(&parent_state.root);
            parser.m_parentParser = Some(
                ::core::num::NonZeroU32::new(
                    parent_state
                        .depth
                        .map_or(0, ::core::num::NonZeroU32::get)
                        .saturating_add(1),
                )
                .expect("child parser depth is non-zero"),
            );
        } else {
            let mut root = parser
                .m_root
                .lock()
                .unwrap_or_else(|poisoned| poisoned.into_inner());
            root.alloc_tracker = alloc_tracker;
            root.allocator_suite_key = parser.m_allocatorKey;
            root.public_memory_releases
                .lock()
                .unwrap_or_else(|poisoned| poisoned.into_inner())
                .null_allocation = Some(null_public_memory_allocation(memory_suite));
        }
        std::sync::Arc::clone(&parser.m_root)
    };
    parser.m_allocationBackingFactory = Some(AllocationBackingFactory::for_pinned_parser(
        std::pin::Pin::new(&*parser),
    ));
    {
        let mut root = root_owner
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        root.allocations.insert(
            parser_ptr.addr(),
            ExpatAllocation {
                payload_size: ::core::mem::size_of::<XML_ParserStruct>(),
            },
        );
        if XmlBigCount::MAX - root.alloc_tracker.bytesAllocated < increase as XmlBigCount {
            std::process::abort();
        }
        root.alloc_tracker.bytesAllocated = root
            .alloc_tracker
            .bytesAllocated
            .wrapping_add(increase as XmlBigCount);
        let allocation_totals = if root.alloc_tracker.debugLevel >= 2 as ::core::ffi::c_ulong {
            if root.alloc_tracker.bytesAllocated > root.alloc_tracker.peakBytesAllocated {
                root.alloc_tracker.peakBytesAllocated = root.alloc_tracker.bytesAllocated;
            }
            Some((
                root.alloc_tracker.bytesAllocated,
                root.alloc_tracker.peakBytesAllocated,
            ))
        } else {
            None
        };
        drop(root);
        if let Some((new_total, peak_total)) = allocation_totals {
            expat_heap_stat(
                &root_owner,
                parser_ptr.addr(),
                '+' as ::core::ffi::c_char,
                increase as XmlBigCount,
                new_total,
                peak_total,
                1439 as ::core::ffi::c_int,
            );
        }
    }
    // The allocation remains private to this constructor until every
    // allocator-backed member has been installed.  In particular, each
    // failure below releases exactly the tokens acquired so far before the
    // parser allocation itself is returned to the configured allocator.
    let storage_result = (|| -> Result<(), ::core::ffi::c_int> {
        parser.m_buffer = InputBuffer::empty();
        parser.m_bufferLim = 0;
        parser.m_attsSize = INIT_ATTS_SIZE;
        let allocation_factory = parser
            .m_allocationBackingFactory
            .as_ref()
            .expect("parser allocation factory is installed during construction");
        let Some(atts) =
            attribute_storage_new(allocation_factory, INIT_ATTS_SIZE as usize, 1449)
        else {
            return Err(1451);
        };
        parser.m_atts = atts;
        let mut data_buf_backing = match parser_allocation_backing(
            parser,
            (INIT_DATA_BUF_SIZE as crate::__stddef_size_t_h::size_t)
                .wrapping_mul(::core::mem::size_of::<crate::expat_external_h::XML_Char>()),
            1462 as ::core::ffi::c_int,
        ) {
            Some(backing) => backing,
            None => {
                let mut backing = parser.m_atts.backing.take();
                if let Some(backing) = backing.as_mut() {
                    backing.apply(ParserAllocationAction::Free(1464));
                }
                return Err(1468);
            }
        };
        let mut data_buf_chars = Vec::new();
        if data_buf_chars
            .try_reserve_exact(INIT_DATA_BUF_SIZE as usize)
            .is_err()
        {
            data_buf_backing(1464 as ::core::ffi::c_int);
            let mut backing = parser.m_atts.backing.take();
            if let Some(backing) = backing.as_mut() {
                backing.apply(ParserAllocationAction::Free(1464));
            }
            return Err(1468);
        }
        data_buf_chars.resize(INIT_DATA_BUF_SIZE as usize, 0);
        parser.m_dataBuf = DataBuffer {
            chars: data_buf_chars,
            backing: Some(data_buf_backing),
        };
        parser.m_dataBufEnd = INIT_DATA_BUF_SIZE as usize;
        if share_parent_dtd {
            parser.m_dtd = parent_state
                .as_ref()
                .and_then(|state| state.inherited_dtd.as_ref())
                .cloned();
        } else {
            parser.m_dtd = dtd_create(parser);
            if parser.m_dtd.is_none() {
                parser.m_dataBuf.release(1478 as ::core::ffi::c_int);
                let mut backing = parser.m_atts.backing.take();
                if let Some(backing) = backing.as_mut() {
                    backing.apply(ParserAllocationAction::Free(1479));
                }
                return Err(1483);
            }
        }
        Ok(())
    })();
    if storage_result.is_err() {
        cleanup_failed_parser_construction(parser);
        return None;
    }
    initialize_parser_collections(parser);
    parser.m_unknownEncodingHandler = false;
    UNKNOWN_ENCODING_HANDLERS
        .get_or_init(|| std::sync::Mutex::new(std::collections::HashMap::new()))
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner())
        .remove(&(parser as *mut XML_ParserStruct as usize));
    UNKNOWN_ENCODING_HANDLER_ARGS
        .get_or_init(|| std::sync::Mutex::new(std::collections::HashMap::new()))
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner())
        .remove(&(parser as *mut XML_ParserStruct as usize));
    let string_pool_allocator = string_pool_allocator(
        parser
            .m_allocationBackingFactory
            .as_ref()
            .expect("parser allocation factory is installed during construction")
            .clone(),
    );
    pool_init(&mut parser.m_tempPool, string_pool_allocator.clone());
    pool_init(&mut parser.m_temp2Pool, string_pool_allocator);
    if !parser_init(
        parser,
        parser_ptr.addr(),
        g_reparseDeferralEnabledDefault.load(std::sync::atomic::Ordering::Relaxed),
        environment_decimal_debug_level("EXPAT_ACCOUNTING_DEBUG", 0),
        environment_decimal_debug_level("EXPAT_ENTITY_DEBUG", 0),
        encoding_name,
    ) {
        cleanup_failed_parser_construction(parser);
        return None;
    }
    if let Some(namespace_separator) = namespace_separator {
        parser.m_ns = crate::expat_h::XML_TRUE;
        parser.m_internalEncoding = InternalEncoding::Utf8Ns;
        parser.m_namespaceSeparator = namespace_separator;
    } else {
        parser.m_internalEncoding = InternalEncoding::Utf8;
    }
    Some(std::pin::Pin::into_inner(parser_owner))
}

