#[export_name = "XML_SetElementHandler"]

pub unsafe extern "C" fn XML_SetElementHandler_ffi(
    mut parser: crate::expat_h::XML_Parser,
    mut start: crate::expat_h::XML_StartElementHandler,
    mut end: crate::expat_h::XML_EndElementHandler,
) {
    if parser.is_null() || !parser.is_aligned() {
        return;
    }
    let parser_address = parser.addr();
    // An end-element callback receives a validated, callback-scoped XML name
    // from `dispatch_end_element_callback`.  Its C ABI is identical; this
    // conversion records that the adapter, rather than every dispatch site,
    // now discharges the callback's pointer preconditions.
    let end: Option<
        extern "C" fn(
            *mut ::core::ffi::c_void,
            *const crate::expat_external_h::XML_Char,
        ),
    > = unsafe { ::core::mem::transmute(end) };
    let parser = unsafe { parser.as_mut() }.expect("non-null parser was checked");
    set_start_element_handler(parser, parser_address, start);
    set_end_element_handler(parser, parser_address, end);
}
fn set_start_element_handler<Callback>(
    parser: &mut XML_ParserStruct,
    parser_address: usize,
    handler: Option<Callback>,
) where
    Callback: StartElementCallback + 'static,
{
    let registration = start_element_handler_registration(handler);
    parser.m_startElementHandler = registration.callback.is_some();
    let mut handlers = START_ELEMENT_HANDLERS
        .get_or_init(|| std::sync::Mutex::new(std::collections::HashMap::new()))
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner());
    match registration.callback {
        Some(callback) => {
            handlers.insert(parser_address, callback);
        }
        None => {
            handlers.remove(&parser_address);
        }
    }
}
