#[derive(Copy, Clone)]
enum EntityTrackingAction {
    Open,
    Close,
}

impl EntityTrackingAction {
    fn label(self) -> &'static str {
        match self {
            Self::Open => "OPEN ",
            Self::Close => "CLOSE",
        }
    }
}

/// Renders the optional entity-tracking diagnostic from checked parser and DTD
/// state.  Entity names stay as XML bytes: reporting must not require them to
/// be valid UTF-8.
struct EntityTrackingReport<'a> {
    root_parser_address: usize,
    count_ever_opened: ::core::ffi::c_uint,
    current_depth: ::core::ffi::c_uint,
    maximum_depth_seen: ::core::ffi::c_uint,
    is_parameter: bool,
    entity_name: &'a [u8],
    action: EntityTrackingAction,
    text_length: ::core::ffi::c_int,
    source_line: ::core::ffi::c_int,
}

fn entityTrackingReportStats(report: EntityTrackingReport<'_>) {
    use std::io::Write;

    let mut stderr = std::io::stderr().lock();
    let _ = write!(
        stderr,
        "expat: Entities(0x{:x}): Count {:>9}, depth {:>2}/{:>2} ",
        report.root_parser_address,
        report.count_ever_opened,
        report.current_depth,
        report.maximum_depth_seen,
    );
    let indentation = (report.current_depth as ::core::ffi::c_int)
        .wrapping_sub(1)
        .wrapping_mul(2)
        .unsigned_abs() as usize;
    for _ in 0..indentation {
        let _ = stderr.write_all(b" ");
    }
    let _ = stderr.write_all(if report.is_parameter { b"%" } else { b"&" });
    let _ = stderr.write_all(report.entity_name);
    let _ = write!(
        stderr,
        "; {} length {} (xmlparse.c:{})\n",
        report.action.label(),
        report.text_length,
        report.source_line,
    );
}

/// Reports entity tracking from parser- and DTD-owned state.  Callers retain
/// typed references for the full report, so this does not need to reconstruct
/// either object from a legacy handle merely to print a diagnostic.
fn entity_tracking_report_stats(
    parser: &XML_ParserStruct,
    entity: &ENTITY,
    action: EntityTrackingAction,
    source_line: ::core::ffi::c_int,
) {
    let (count_ever_opened, current_depth, maximum_depth_seen) = {
        let stats = parser
            .m_root
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        if stats.entity_stats.debugLevel == 0 {
            return;
        }
        (
            stats.entity_stats.countEverOpened,
            stats.entity_stats.currentDepth,
            stats.entity_stats.maximumDepthSeen,
        )
    };
    let Some(dtd) = parser.m_dtd.as_deref() else {
        return;
    };
    dtd.inspect(|dtd| {
        let Some(entity_name) = pool_terminated_chars(&dtd.pool, entity.named.name) else {
            return;
        };
        let Some(entity_name) = entity_name.strip_suffix(&[0]) else {
            return;
        };
        entityTrackingReportStats(EntityTrackingReport {
            root_parser_address: std::ptr::from_ref(parser).addr(),
            count_ever_opened,
            current_depth,
            maximum_depth_seen,
            is_parameter: entity.is_param != 0,
            entity_name: bytemuck::cast_slice(entity_name),
            action,
            text_length: entity.textLen,
            source_line,
        });
    });
}

/// Updates tracking after opening an entity that is already held in the DTD's
/// typed table.
fn entity_tracking_on_open(
    parser: &mut XML_ParserStruct,
    entity: &ENTITY,
    source_line: ::core::ffi::c_int,
) {
    {
        let mut root = parser
            .m_root
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        root.entity_stats.countEverOpened = root.entity_stats.countEverOpened.wrapping_add(1);
        root.entity_stats.currentDepth = root.entity_stats.currentDepth.wrapping_add(1);
        if root.entity_stats.currentDepth > root.entity_stats.maximumDepthSeen {
            root.entity_stats.maximumDepthSeen = root.entity_stats.maximumDepthSeen.wrapping_add(1);
        }
    }
    entity_tracking_report_stats(parser, entity, EntityTrackingAction::Open, source_line);
}

/// Reports and closes a typed entity-tracking scope without returning to raw
/// parser or entity handles.
fn entity_tracking_on_close(
    parser: &mut XML_ParserStruct,
    entity: &ENTITY,
    source_line: ::core::ffi::c_int,
) {
    entity_tracking_report_stats(parser, entity, EntityTrackingAction::Close, source_line);
    let mut root = parser
        .m_root
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner());
    root.entity_stats.currentDepth = root.entity_stats.currentDepth.wrapping_sub(1);
}

const fn printable_hex_digit(value: u8) -> u8 {
    match value {
        0..=9 => b'0' + value,
        _ => b'A' + (value - 10),
    }
}

const fn printable_byte(c: u8) -> [u8; 5] {
    let mut printable = [0; 5];
    match c {
        0 => {
            printable[0] = b'\\';
            printable[1] = b'0';
        }
        b'\t' => {
            printable[0] = b'\\';
            printable[1] = b't';
        }
        b'\n' => {
            printable[0] = b'\\';
            printable[1] = b'n';
        }
        b'\r' => {
            printable[0] = b'\\';
            printable[1] = b'r';
        }
        32..=126 if c == b'"' || c == b'\\' => {
            printable[0] = b'\\';
            printable[1] = c;
        }
        32..=126 => printable[0] = c,
        _ => {
            printable[0] = b'\\';
            printable[1] = b'x';
            if c < 16 {
                printable[2] = printable_hex_digit(c);
            } else {
                printable[2] = printable_hex_digit(c >> 4);
                printable[3] = printable_hex_digit(c & 0x0f);
            }
        }
    }
    printable
}

const fn printable_byte_table() -> [[u8; 5]; 256] {
    let mut table = [[0; 5]; 256];
    let mut index = 0;
    while index < table.len() {
        table[index] = printable_byte(index as u8);
        index += 1;
    }
    table
}

static PRINTABLE_BYTES: [[u8; 5]; 256] = printable_byte_table();

fn unsignedCharToPrintable(c: ::core::ffi::c_uchar) -> &'static [u8; 5] {
    &PRINTABLE_BYTES[c as usize]
}
#[export_name = "unsignedCharToPrintable"]

pub unsafe extern "C" fn unsignedCharToPrintable_ffi(
    c: ::core::ffi::c_uchar,
) -> *const ::core::ffi::c_char {
    unsignedCharToPrintable(c).as_ptr().cast()
}
